	{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"안건"}]},
	{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"항목"}]}]}]}
